"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3740],{43740:e=>{e.exports=JSON.parse('{"slug":"ipoteka-sentyabr-2026-rekord-vydachi","locale":"zh","title":"家庭房贷收紧前，银行九月发放608.5十亿卢布按揭","description":"2026年九月银行发放123.8千笔、共608.5十亿卢布房贷。回顾此前政策截止日前抢办后的变化。","blocks":[{"id":"b001","kind":"paragraph","text":"2026年九月，俄罗斯银行发放123.8千笔按揭，共608.5十亿卢布。合同数量较八月增45%，金额增63%，为2025年十二月802.9十亿以来最高。大部分来自家庭房贷。VTB房贷负责人谢尔盖\xb7巴宾估计该项目九月约385十亿卢布，是八月的2倍。"},{"id":"b002","kind":"paragraph","text":"家庭赶在条件改变前办理。自2026年十月1日，家庭房贷利率按子女人数和地区区分，此前统一6%。有1个孩子者，地方10%，莫斯科、圣彼得堡及周边12%；有2个者分别8%和10%。九月30日及之前签约保持旧条件。最后一天Sber办理7.4千笔、46.6十亿卢布，创项目1天纪录。"},{"id":"b003","kind":"paragraph","text":"类似商店宣布涨价前抢购，后面数周顾客就少。部分九月交易只是提前发生，这称截止日效应。2026年房贷已有2次：2026年一月，在二月1日禁止每家超过1笔优惠房贷前发约420十亿卢布，二月290.3十亿，少31%。六月，市场预计七月1日收紧，发放较五月增48%；六月29日财政部推迟到十月，但七月仍降25%。"},{"id":"b004","kind":"paragraph","text":"其他贷款九月未增长。2026年九月居民共借3.14百万笔、1.33万亿卢布，比八月金额多20.8%。现金贷款515.4十亿，约持平，汽车贷款少2%。央行关键利率14%下，普通贷款昂贵，人们未增加借款。"},{"id":"b005","kind":"paragraph","text":"以地方有1个孩子的家庭计算：6百万卢布、30年、6%房贷，月供约36千卢布；同一贷款按10%，前15年约52.7千。此类家庭只有2种情况仍可享不超过6%：孩子残疾，或首付达到房价50%。"},{"id":"b006","kind":"paragraph","text":"十月发放数据十一月初公布。若大跌，意味着九月透支后续需求，如二月和七月。若保持，说明家庭愿承担10–12%。有1个孩子而没赶上的家庭，如今利率比旧标准高4–6个百分点。家庭房贷利率由项目定，央行降关键利率也不会自动降低。推迟购房要继续付租金，房价是否下跌则未知。"},{"id":"b007","kind":"heading","text":"2026年九月房贷发放为何增加？"},{"id":"b008","kind":"paragraph","text":"从2026年十月1日，有1和2个孩子的家庭利率由6%升至8–12%，因此赶旧条件签约。九月发608.5十亿卢布，比八月多63%。"},{"id":"b009","kind":"heading","text":"此前收紧家庭房贷后怎样？"},{"id":"b010","kind":"paragraph","text":"发放下降。2026年二月在一月抢办后仅290.3十亿卢布，少31%。七月在六月激增后降25%，尽管政策延期、条件未变。"},{"id":"b011","kind":"heading","text":"九月签的家庭房贷会保留6%吗？"},{"id":"b012","kind":"paragraph","text":"会。新条件只适用于2026年十月1日起签约者，九月30日及之前签约继续旧利率。"}],"sources":[{"label":"核心政府项目收紧前房贷激增","url":"https://thebell.io/vydachi-ipoteki-podskochili-pered-uzhestocheniem-klyuchevoy-gosprogrammy"},{"label":"九月俄罗斯房贷发放创纪录","url":"https://realty.rbc.ru/news/6ac352bc89d57af63b2fbdf8"},{"label":"2026年九月家庭房贷：改革前抢办","url":"https://www.sravni.ru/text/semeynaya-ipoteka-rekord-sentyabr-2026/"},{"label":"2025年十二月家庭房贷创1.5年新高","url":"https://finance.mail.ru/article/vyidachi-semejnoj-ipoteki-v-dekabre-2025-goda-dostigli-maksimuma-za-15-goda-69195191/"},{"label":"家庭房贷条件收紧后，二月发放下降近三分之一","url":"https://ru.themoscowtimes.com/2026/03/06/vidacha-ipoteki-v-fevrale-ruhnula-na-tret-posle-uzhestocheniya-uslovii-dlya-semeinih-rossiyan-a189017"},{"label":"央行：六月激增后七月房贷降至363十亿卢布","url":"https://finuslugi.ru/navigator/news/novosti_bankovskoj_otrasli/tsb-vydachi-ipoteki-upali-do-363-mlrd-v-iyule-rynok-ostyl-posle-iyunskogo-vspleska"},{"label":"财政部宣布保留家庭房贷现有条件","url":"https://finance.mail.ru/article/minfin-perenes-izmeneniya-semejnoj-ipoteki-do-oktyabrya-69215609/"},{"label":"俄罗斯央行维持关键利率14%","url":"https://www.cbr.ru/press/keypr/"}],"sourceBodySha256":"69a454caaee0d4b2b465e488d24b624bdcc43ee4fb07418714c00cd6de309533"}')}}]);